    patient_data = json.load(f)
with open('json/Examination.json') as f:
    exam_data = json.load(f)

patient_dict = {p['ID']: p for p in patient_data['records']}
severe_patients = []
for e in exam_data['records']:
    if e.get('Thrombosis') == 2:
        pid = e['ID']
        if pid in patient_dict:
            p = patient_dict[pid]
            severe_patients.append({
                'ID': pid,
                'SEX': p['SEX'],
                'Diagnosis': p['Diagnosis']
            })

